$topics = @(
  @{slug='fermuar-cepli-polo-is-tisortu-secim-rehberi';title='Fermuar Cepli Polo İş Tişörtü Seçim Rehberi';summary='Fermuarlı göğüs cepli polo iş tişörtünde kumaş, cep konumu, kurumsal renk ve logo uygulamasını görev ihtiyaçlarına göre planlayın.';category='Ürün Rehberleri';product='KT-TS-037 Lacivert Petrol Fermuar Cepli Polo İş Tişörtü';productUrl='/urun/kt-ts-037-lacivert-petrol-fermuar-cepli-polo-s-tisortu/';categoryUrl='/polo-yaka-is-tisortu/';need='kart, kalem veya küçük ekipmanın kontrollü taşınması';material='lakost ya da penye örme kumaşın cep ağırlığıyla sarkmaması';test='cebe erişim, fermuar hareketi, oturma ve öne uzanma';related=@('polo-yaka-tisort-rehberi-2026','is-kiyafetinde-gorev-bazli-cep-standardi','polo-tisortte-logo-yerlesimi')},
  @{slug='teknik-sweatshirt-katmanlama-ve-cep-secimi';title='Teknik Sweatshirt Katmanlama ve Cep Seçimi';summary='Teknik sweatshirt seçiminde yarım fermuar, kapüşon, dirsek takviyesi ve cep düzenini çalışma sıcaklığı ile hareket yoğunluğuna göre karşılaştırın.';category='Ürün Rehberleri';product='KT-SW-034 Grafit Petrol Teknik Sweatshirt';productUrl='/urun/kt-sw-034-grafit-petrol-yarim-fermuarli-teknik-sweatshirt/';categoryUrl='/kurumsal-is-sweatshirtu/';need='serin iç ortam ile açık saha arasında dengeli katmanlama';material='iki veya üç iplik örme kumaşın gramaj ve iç yüzey yapısı';test='kol hareketi, yarım fermuar havalandırması ve dış katman uyumu';related=@('sweatshirt-is-kiyafeti-rehberi','dort-mevsim-is-kiyafeti-planlama-rehberi','is-ceketinde-dirsek-takviyesi')},
