  @{slug='polar-mi-softshell-mi-hangi-kosulda';title='Polar mı Softshell mi? Hangi Koşulda Hangisi Seçilir?';summary='Polar ve softshell iş montlarını ısı yalıtımı, rüzgâr, hafif yağış, nefes alma, hareket ve katmanlama ölçütleriyle karşılaştırın.';category='Kumaş ve Teknik Bilgi';product='KT-PL-025 Grafit Petrol Polar Mont';productUrl='/urun/kt-pl-025-grafit-petrol-tam-fermuarli-polar-mont/';categoryUrl='/polar-is-montu/';need='iç ortam ısısı ile rüzgârlı dış saha arasında doğru üst katmanı seçmek';material='polar yüzeyin ısı tutması ile softshell yüzeyin rüzgâr direnci';test='aynı görevde sıcaklık, terleme, rüzgâr ve hareket karşılaştırması';related=@('polar-kumas-nedir','softshell-kumas-nedir','dort-mevsim-is-kiyafeti-rehberi')},
  @{slug='yazlik-ve-kislik-is-yelegi-farki';title='Yazlık ve Kışlık İş Yeleği Arasındaki Farklar';summary='İç dolgusuz yazlık iş yeleği ile silikon dolgulu kışlık yeleği cep düzeni, ısı, hareket, katman ve kullanım alanına göre karşılaştırın.';category='Ürün Rehberleri';product='KT-YL-022 Grafit Turuncu Yazlık İş Yeleği';productUrl='/urun/kt-yl-022-grafit-turuncu-cok-cepli-yazlik-s-yelegi/';categoryUrl='/reflektorlu-is-yelegi/';need='kol hareketini serbest bırakırken mevsime uygun gövde katmanı sağlamak';material='hafif dokuma yüzey ile kapitone ve silikon dolgunun farkı';test='araç kullanma, eğilme, ceplere erişim ve dış katman uyumu';related=@('is-yelegi-secim-rehberi-2026','kapitoneli-is-yelegi-rehberi','polar-is-yelegi-rehberi')},
  @{slug='ikaz-yeleginde-reflektif-bant-ve-cep-duzeni';title='İkaz Yeleğinde Reflektif Bant ve Cep Düzeni';summary='İkaz yeleğinde zemin rengi, reflektif bant yerleşimi, cep, kimlik bölmesi, telsiz askısı ve logo alanını görev riskine göre planlayın.';category='İş Güvenliği';product='KT-IY-011 Fosfor Sarı Lacivert Cepli İkaz Yeleği';productUrl='/urunlerimiz#isg';categoryUrl='/is-guvenligi-ekipmanlari/';need='araç ve ekipman trafiğinde çalışanın farklı açılardan fark edilmesi';material='görünür zemin, reflektif bileşen ve kenar dikişlerinin bütünlüğü';test='gündüz, düşük ışık, farklı görüş açıları ve cepler doluyken kullanım';related=@('reflektorlu-is-yelegi-secim-rehberi','yuksek-gorunurluklu-is-kiyafetleri-siniflari','yuksek-gorunurluklu-kiyafete-logo')},
  @{slug='urun-kodundan-teknik-sartnameye-katalog-yonetimi';title='Ürün Kodundan Teknik Şartnameye Katalog Yönetimi';summary='Katalogdaki ürün kodunu kumaş, renk, cep, beden, logo ve numune kayıtlarıyla eşleştirerek tekrar siparişlerde yorum farkını azaltın.';category='Satın Alma Rehberi';product='Kardeşler Tekstil ürün kataloğu';productUrl='/urunlerimiz';categoryUrl='/urunlerimiz';need='çok sayıda model arasından onaylanan ürünü değişmeden yeniden sipariş etmek';material='ürün koduna bağlanan kumaş, aksesuar, renk ve ölçü referansları';test='numune, teknik föy, beden tablosu ve teslim edilen ürün karşılaştırması';related=@('is-kiyafeti-urun-kodlama-standardi-nasil-kurulur','is-kiyafeti-sartname-hazirlama-rehberi','is-kiyafeti-numune-onay-akisi')}
)
if ($topics.Count -ne 10) { throw '10 makale bekleniyordu.' }
function E([string]$s) { [Net.WebUtility]::HtmlEncode($s) }
function J($o) { $o | ConvertTo-Json -Depth 10 -Compress }
$utf8 = New-Object Text.UTF8Encoding($false)
$dataPath = Join-Path $center 'knowledge-center.js'
$data = [IO.File]::ReadAllText($dataPath, [Text.Encoding]::UTF8)
$rows = @()
foreach ($t in $topics) {
  $url = "https://kardeslertekstil.com.tr/bilgi-merkezi/$($t.slug)/"
  $links = ($t.related | ForEach-Object { "<a data-link-role=`"guide`" href=`"../$_/`">$(E (($_ -replace '-', ' ') -replace '\b\w', { $args[0].Value.ToUpper() }))</a>" }) -join ''
  $schema = [ordered]@{'@context'='https://schema.org';'@type'='BlogPosting';'@id'="$url#article";headline=$t.title;description=$t.summary;url=$url;mainEntityOfPage=@{'@type'='WebPage';'@id'=$url};image=@('https://kardeslertekstil.com.tr/assets/logo-kit-badge.webp');datePublished=$date;dateModified=$date;inLanguage='tr-TR';articleSection=$t.category;author=@{'@type'='Organization';'@id'='https://kardeslertekstil.com.tr/#organization';name='Kardeşler Tekstil'};publisher=@{'@type'='Organization';'@id'='https://kardeslertekstil.com.tr/#organization';name='Kardeşler Tekstil'}}
  $breadcrumb = [ordered]@{'@context'='https://schema.org';'@type'='BreadcrumbList';itemListElement=@(@{'@type'='ListItem';position=1;name='Ana Sayfa';item='https://kardeslertekstil.com.tr/'},@{'@type'='ListItem';position=2;name='Bilgi Merkezi';item='https://kardeslertekstil.com.tr/bilgi-merkezi/'},@{'@type'='ListItem';position=3;name=$t.title;item=$url})}
  $html = @"
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>$(E $t.title) | Kardeşler Tekstil</title><meta name="description" content="$(E $t.summary)"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="$url"><meta property="og:type" content="article"><meta property="og:locale" content="tr_TR"><meta property="og:site_name" content="Kardeşler Tekstil"><meta property="og:title" content="$(E $t.title)"><meta property="og:description" content="$(E $t.summary)"><meta property="og:url" content="$url"><meta property="og:image" content="https://kardeslertekstil.com.tr/assets/logo-kit-badge.webp"><meta property="article:published_time" content="$date"><meta property="article:modified_time" content="$date"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="$(E $t.title)"><meta name="twitter:description" content="$(E $t.summary)"><meta name="twitter:image" content="https://kardeslertekstil.com.tr/assets/logo-kit-badge.webp"><link rel="stylesheet" href="../../styles.css?v=20260807-6"><script type="application/ld+json">$(J $schema)</script><script type="application/ld+json">$(J $breadcrumb)</script><script src="../knowledge-center.js?v=20260807-3" defer></script><script src="/site.js?v=20260804-2" defer></script></head><body data-post-slug="$($t.slug)"><header class="site-header"><div class="container"><a class="brand" href="../../"><img src="../../assets/logo-kit-badge.webp" alt="Kardeşler Tekstil" width="1424" height="940"></a><nav class="nav" aria-label="Ana navigasyon"><a href="../../">Ana Sayfa</a><a href="../../urunlerimiz">Ürünlerimiz</a><a href="../../referanslarimiz">Referanslarımız</a><a href="../../hakkimizda">Hakkımızda</a><a href="../">Bilgi Merkezi</a><a href="../../iletisim">İletişim</a></nav><a class="btn btn-accent" href="../../iletisim#teklif-formu">Teklif Al</a></div></header><div class="container knowledge-breadcrumb"><nav aria-label="Breadcrumb"><ol><li><a href="../../">Ana Sayfa</a></li><li><a href="../">Bilgi Merkezi</a></li><li aria-current="page">$(E $t.title)</li></ol></nav></div><main class="knowledge-article"><div class="container knowledge-article-layout"><article class="knowledge-article-main"><span class="category">$(E $t.category)</span><h1>$(E $t.title)</h1><p class="intro">$(E $t.summary)</p><div class="knowledge-article-meta"><span>Yayınlanma: <time datetime="$date">7 Ağustos 2026</time></span><span>Son güncelleme: <time datetime="$date">7 Ağustos 2026</time></span><span>8 dk okuma</span></div><section><h2>Karar önce görev tanımıyla başlar</h2><p>Bu ürün grubunda doğru seçim yalnız katalog görünümüne göre yapılamaz. Temel ihtiyaç, $(E $t.need) olarak tanımlanmalıdır. Çalışma alanı, vardiya süresi, iklim, hareket yoğunluğu ve birlikte kullanılan kişisel koruyucu donanımlar yazılı hale getirilmeden renk ve model kararı vermek, numune aşamasında gereksiz revizyona yol açar.</p><p>Satın alma ekibi görevleri tek bir personel başlığı altında toplamak yerine kullanım senaryolarını ayırmalıdır. Aynı departmandaki saha, depo, araç ve müşteri alanı görevleri farklı cep, katman ve görünürlük ihtiyacı doğurabilir. Bu ayrım ürün setini sadeleştirirken gerçekten gerekli özelliklerin korunmasını sağlar.</p></section><section><h2>Kumaş ve yapı nasıl değerlendirilir?</h2><p>Malzeme seçiminde $(E $t.material) kontrol edilmelidir. Gramaj tek başına kalite göstergesi değildir; dikiş dayanımı, çekme, renk haslığı, tüylenme, hava geçirgenliği ve aksesuarların yıkama davranışı birlikte ele alınmalıdır.</p><p>Kontrast paneller, biyeler ve reflektif parçalar yalnız görsel amaçla eklenmemelidir. Her parça üretilebilir bir kesim hattına bağlanmalı, hareketi engellememeli ve kurumsal logo için yeterli düz alan bırakmalıdır. Koruyucu standart iddiası gerekiyorsa özellikler üretici beyanı ve uygun belgeyle ayrıca doğrulanmalıdır.</p></section><section><h2>Numunede hangi hareketler denenmeli?</h2><p>Numune kontrolünde $(E $t.test) gözlenmelidir. Temsilci kullanıcılar yalnız ayakta dururken değil, gerçek görev hareketleri sırasında ürünü denemeli; çekme, baskı, açılma, sarkma ve erişim sorunları ürün bölgesi belirtilerek kaydedilmelidir.</p><p>Beden tablosu, kumaş referansı, renk kodu, aksesuar tipi, logo ölçüsü ve konumu onay formuna bağlanmalıdır. Fotoğraf tek başına teknik kayıt değildir; onaylanan numunenin ürün kodu ve revizyon tarihiyle saklanması tekrar siparişlerde yorum farkını azaltır.</p></section><section><h2>Bakım ve kullanım ömrü</h2><p>Yıkama sıcaklığı, kurutma yöntemi ve leke müdahalesi kumaş ile logo uygulamasına göre belirlenmelidir. Fermuarlar kapatılmalı, cırt bantlar diğer yüzeylere zarar vermeyecek biçimde sabitlenmeli ve reflektif alanlarda üretici bakım talimatı izlenmelidir. Hasarlı ürünün tamir ya da değişim eşiği kurum içinde açıkça tanımlanmalıdır.</p><p>Ürün ömrünü ölçmek için teslim tarihi, kullanım sıklığı, yıkama döngüsü ve hasar nedeni birlikte izlenebilir. Böylece yalnız birim fiyat yerine kullanım başına maliyet karşılaştırılır ve sonraki koleksiyonda hangi detayın korunacağı kanıta dayalı olarak belirlenir.</p><p>Kontrol sonuçları departman, ürün kodu ve beden kırılımında aylık olarak incelenmelidir. Aynı bölgede tekrar eden sökülme, renk değişimi veya fermuar sorunu görülüyorsa yalnız ürünü yenilemek yerine neden analizi yapılmalıdır. Yanlış beden dağılımı, uygun olmayan yıkama programı ve görevle uyuşmayan cep yükü benzer hasarı yeniden üretebilir. Satın alma, kullanıcı ve üretim ekiplerinin aynı kayıt üzerinden değerlendirme yapması; düzeltmenin kumaşta mı, kalıpta mı, aksesuarda mı yoksa kullanım eğitiminde mi gerektiğini ayırmayı sağlar. Bir sonraki siparişte değişiklik yapılırsa eski ve yeni revizyon aynı anda dağıtılmamalı, ürün kodu veya revizyon ekiyle ayrıştırılmalıdır.</p></section><section class="knowledge-seo-links" data-seo-enhancement="knowledge-v3" aria-label="İlgili ürün ve rehberler"><div class="eyebrow eyebrow-accent">İLGİLİ ÇÖZÜMLER</div><h2>Ürün ve okuma bağlantıları</h2><div class="knowledge-seo-link-grid"><a data-link-role="category" href="$($t.categoryUrl)"><strong>Kategori seçeneklerini inceleyin</strong><span>Modelleri ve üretim kapsamını karşılaştırın.</span></a><a data-link-role="product" href="$($t.productUrl)"><strong>$(E $t.product)</strong><span>Ürün görseli, SKU ve teknik açıklamayı inceleyin.</span></a></div><nav class="knowledge-related-links" aria-label="İlgili rehberler">$links</nav><p class="knowledge-review-note">Hazırlayan ve kontrol eden: <a href="../../hakkimizda">Kardeşler Tekstil Üretim Ekibi</a> · <a data-link-role="quote" href="../../iletisim#teklif-formu">Projeniz için teklif isteyin</a></p></section></article></div></main><footer class="site-footer"><div class="container"><p>© 2026 Kardeşler Tekstil. Tüm hakları saklıdır.</p></div></footer></body></html>
"@
  $dir = Join-Path $center $t.slug
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  [IO.File]::WriteAllText((Join-Path $dir 'index.html'), $html, $utf8)
  $rows += '{"slug":' + (J $t.slug) + ',"title":' + (J $t.title) + ',"summary":' + (J $t.summary) + ',"category":' + (J $t.category) + ',"tags":["Yeni Rehber"],"searchTerms":[' + (J $t.title) + ',' + (J ($t.slug -replace '-', ' ')) + '],"published":"' + $date + '","views":0},'
}
$data = $data.Replace('  const posts = [', "  const posts = [`r`n$($rows -join "`r`n")")
[IO.File]::WriteAllText($dataPath, $data, $utf8)
Write-Output '10 bilgi merkezi makalesi oluşturuldu.'
